{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/hero-split-media.json
    What HeroSplit shows beside the text: a picture, a picture with a floating card, a grid of four pictures with captions, or a picture with two plan cards floating over it.
    Props (p): content, alt, media. -#}
{%- set v_content = (p.content ?? null) -%}
{%- set v_alt = (p.alt ?? null) -%}
{%- set v_media = (p.media ?? 'picture') -%}
{%- if ui_t(ui_eq(v_media, 'picture')) %}
  {{ include('blocks/media-frame.html.twig', {'p': {'alt': v_alt, 'ratio': '4/3'}}, with_context = false) }}
{%- endif %}
{%- if ui_t(ui_eq(v_media, 'card')) %}
  {{ include('blocks/offer-media.html.twig', {'p': {'alt': v_alt, 'card': ui_get(v_content, ['card'])}}, with_context = false) }}
{%- endif %}
{%- if ui_t(ui_eq(v_media, 'grid')) %}
  {%- set c_3 -%}
    {%- for v_f in ui_l(ui_get(v_content, ['features'])) %}
      {%- set v_i = loop.index0 -%}
      {%- if ui_t(ui_lt(v_i, 4)) %}
        {%- set c_2 -%}
          {{ include('blocks/media-frame.html.twig', {'p': {'alt': ui_get(v_f, ['title']), 'ratio': '1/1'}}, with_context = false) }}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_f, ['title'])) }}
          {%- endset -%}
          {{ include('ui/text/text.html.twig', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_1}, with_context = false) }}
        {%- endset -%}
        {{ include('blocks/figure-block.html.twig', {'p': {'className': ui_cnv(['flex flex-col gap-2']), 'testid': 'hero-tile'}, 'children': c_2}, with_context = false) }}
      {%- endif %}
    {%- endfor %}
  {%- endset -%}
  {{ include('ui/box/box.html.twig', {'p': {'Class': 'grid grid-cols-2 gap-4', 'Attrs': ui_attrs(['data-testid', 'hero-grid'])}, 'children': c_3}, with_context = false) }}
{%- endif %}
{%- if ui_t(ui_eq(v_media, 'plans')) %}
  {%- set c_8 -%}
    {{ include('blocks/media-frame.html.twig', {'p': {'alt': v_alt, 'ratio': '4/3'}}, with_context = false) }}
    {%- for v_p in ui_l(ui_get(v_content, ['plans'])) %}
      {%- set v_i = loop.index0 -%}
      {%- if ui_t(ui_lt(v_i, 2)) %}
        {%- set c_7 -%}
          {%- set c_4 -%}
            {{ ui_text(ui_get(v_p, ['name'])) }}
          {%- endset -%}
          {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Weight': 'semibold'}, 'children': c_4}, with_context = false) }}
          {%- set c_6 -%}
            {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'check', 'Size': 16}}, with_context = false) }}
            {%- set c_5 -%}
              {{ ui_text(ui_get(v_p, ['tagline'])) }}
            {%- endset -%}
            {{ include('ui/text/text.html.twig', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_5}, with_context = false) }}
          {%- endset -%}
          {{ include('ui/group/group.html.twig', {'p': {'Gap': '2', 'Align': 'center'}, 'children': c_6}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '2', 'Class': ui_s(ui_cnv(['absolute w-48 rounded bg-card p-4 shadow-lg', (ui_t(ui_eq(v_i, 0)) ? 'top-8 left-4' : 'right-4 bottom-8')])), 'Attrs': ui_attrs(['data-testid', 'hero-plan'])}, 'children': c_7}, with_context = false) }}
      {%- endif %}
    {%- endfor %}
  {%- endset -%}
  {{ include('ui/box/box.html.twig', {'p': {'Class': 'relative', 'Attrs': ui_attrs(['data-testid', 'hero-media'])}, 'children': c_8}, with_context = false) }}
{%- endif %}
